export function listTasks(userId: number) {
  return db.tasks.find({ where: { userId }, order: { dueDate: 'asc' } })
}

ad6e7f8091a2b3c4d5e6f7a1b2c3d4e5f6071829:
export function createTask(userId: number, title: string, dueDate?: string) {
  return db.tasks.create({ userId, title, dueDate, completed: false })
}
